sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputTexture(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputTexture(uv);if(tex==1) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_count;
uniform float amzp_angle_x;
uniform float amzp_angle_y;
uniform float amzp_angle_z;
uniform float amzp_posX;
uniform float amzp_posY;
uniform float amzp_posZ;
uniform float amzp_spread;
uniform float amzp_pSize;
uniform float amzp_shapeType;
layout(color) uniform half4 amzp_colorNear;
layout(color) uniform half4 amzp_colorFar;
uniform float amzp_depthMix;
uniform float amzp_hueFreq;
uniform float amzp_overdrawOn;
    float3 hsv2rgb(float3 c) {
        float4 K = float4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
        float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
        return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
    }
    float3 rgb2hsv(float3 c) {
        float4 K = float4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
        float4 p = mix(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
        float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
        float d = q.x - min(q.w, q.y);
        float e = 1.0e-10;
        return float3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
    }
    void amzRender() {
        float2 uv = (amzLayerNorm() * layer - 0.5 * layer) / layer.y;
        float4 accumulated = float4(0.0);
        float cx = cos(amzp_angle_x), sx = sin(amzp_angle_x);
        float cy = cos(amzp_angle_y), sy = sin(amzp_angle_y);
        float cz = cos(amzp_angle_z), sz = sin(amzp_angle_z);
        float3x3 rx = float3x3(1,0,0, 0,cx,-sx, 0,sx,cx);
        float3x3 ry = float3x3(cy,0,sy, 0,1,0, -sy,0,cy);
        float3x3 rz = float3x3(cz,-sz,0, sz,cz,0, 0,0,1);
        float3x3 rot = rz * ry * rx;
        for(float i=0.0; i<200.0; i++) {
            if (i >= amzp_count) break;
            float3 p = float3(
                fract(sin(i*123.45)*456.78),
                fract(sin(i*234.56)*567.89),
                fract(sin(i*345.67)*678.90)
            );
            p = (p - 0.5) * amzp_spread;
            p += float3(
                sin(time + p.y * 2.0) * 0.1,
                cos(time * 0.8 + p.x * 1.5) * 0.1,
                sin(time * 1.2 + p.z * 3.0) * 0.1
            );
            float3 amzLocal_pos = (rot * p) + float3(amzp_posX, amzp_posY, amzp_posZ);
            float cameraDist = 3.5;
            float z = amzLocal_pos.z + cameraDist;
            if(z > 0.1) {
                float2 projPos = amzLocal_pos.xy / z;
                float2 rel = uv - projPos;
                float normZ = clamp((z - 0.1) / 5.0, 0.0, 1.0);
                float3 pCol = mix(amzp_colorNear.rgb, amzp_colorFar.rgb, normZ * amzp_depthMix);
                if (amzp_hueFreq > 0.0) {
                    float3 hsv = rgb2hsv(pCol);
                    hsv.x = fract(hsv.x + time * amzp_hueFreq + i * 0.02);
                    pCol = hsv2rgb(hsv);
                }
                float brightness = 0.0;
                float4 texCol = float4(1.0);
                if (int(amzp_shapeType) == 0) {
                    brightness = (0.0015 * amzp_pSize) / (dot(rel, rel) + 0.00005);
                } else if (int(amzp_shapeType) == 1) {
                    float s = 0.01 * amzp_pSize / z;
                    brightness = smoothstep(s, s * 0.8, length(rel)) * 5.0;
                } else if (int(amzp_shapeType) == 2) {
                    float s = 0.01 * amzp_pSize / z;
                    brightness = smoothstep(s, s * 0.8, max(abs(rel.x), abs(rel.y))) * 5.0;
                } else if (int(amzp_shapeType) == 3) {
                    float s = 0.015 * amzp_pSize / z;
                    float dStar = min(abs(rel.x), abs(rel.y)) + length(rel) * 0.6;
                    brightness = smoothstep(s, s * 0.5, dStar) * 10.0;
                } else if (int(amzp_shapeType) == 4) {
                    brightness = (0.0015 * amzp_pSize) / (rel.x*rel.x * 20.0 + rel.y*rel.y + 0.00005);
                } else {
                    float s = 0.05 * amzp_pSize / z;
                    float2 texUV = rel / (s * 2.0) + 0.5;
                    if (texUV.x >= 0.0 && texUV.x <= 1.0 && texUV.y >= 0.0 && texUV.y <= 1.0) {
                        texCol = amzTexture(0, texUV);
                        brightness = texCol.a * 1.5;
                    }
                }
                accumulated += float4(pCol * brightness * texCol.rgb, brightness) * (1.0 / (z*z));
            }
        }
        float3 finalCol = pow(accumulated.rgb, float3(0.4545));
        amzOutput = float4(finalCol, clamp(accumulated.a, 0.0, 1.0));
      if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(1, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
